-- ES/DE/FR translations for all 11 Portugal milestones.
-- INSERT OR IGNORE, safe against existing English rows.

INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pt-saft-introduced', 'es', 'Se introduce el archivo de auditoría digital SAF-T', 'La base del sistema moderno de fiscalización de Portugal, mucho antes de que existiera cualquier mandato de facturación electrónica — este formato de archivo sustenta las obligaciones de reporte que llegaron después.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pt-saft-introduced', 'de', 'Digitale Prüfdatei SAF-T eingeführt', 'Die Grundlage von Portugals modernem Fiskalisierungssystem, lange bevor überhaupt eine E-Invoicing-Vorgabe existierte — dieses Dateiformat untermauert die später eingeführten Meldepflichten.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pt-saft-introduced', 'fr', 'Le fichier d''audit numérique SAF-T est introduit', 'Le fondement du système de fiscalisation moderne du Portugal, bien avant l''existence d''une quelconque obligation de facturation électronique — ce format de fichier sous-tend les obligations de déclaration apparues par la suite.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pt-certified-software', 'es', 'El software de facturación certificado se vuelve obligatorio', 'El verdadero inicio del sistema fiscal moderno de Portugal: todas las facturas, independientemente del formato, deben emitirse usando software certificado por la Autoridade Tributária (AT).', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pt-certified-software', 'de', 'Zertifizierte Rechnungssoftware wird verpflichtend', 'Der eigentliche Beginn von Portugals modernem Steuersystem: Alle Rechnungen, unabhängig vom Format, müssen mit von der Autoridade Tributária (AT) zertifizierter Software ausgestellt werden.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pt-certified-software', 'fr', 'Le logiciel de facturation certifié devient obligatoire', 'Le véritable point de départ du système fiscal moderne du Portugal : toutes les factures, quel que soit leur format, doivent être émises à l''aide d''un logiciel certifié par l''Autoridade Tributária (AT).', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pt-lei-111b', 'es', 'La Ley n.º 111-B/2017 transpone la directiva de la UE sobre contratación pública', 'Establece la base legal para el régimen de facturación electrónica B2G de Portugal, implementando la Directiva UE 2014/55/EU en la legislación nacional.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pt-lei-111b', 'de', 'Gesetz Nr. 111-B/2017 setzt die EU-Richtlinie zur öffentlichen Auftragsvergabe um', 'Schafft die Rechtsgrundlage für Portugals B2G-E-Invoicing-Regime und setzt die EU-Richtlinie 2014/55/EU in nationales Recht um.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pt-lei-111b', 'fr', 'La loi n° 111-B/2017 transpose la directive de l''UE sur les marchés publics', 'Établit la base légale du régime de facturation électronique B2G du Portugal, transposant la directive UE 2014/55/UE dans le droit national.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pt-public-bodies-receive', 'es', 'Los organismos públicos deben recibir y procesar facturas electrónicas', 'Las entidades de la administración pública quedan obligadas a recibir y procesar facturas electrónicas estructuradas, a través de la plataforma centralizada operada por eSPap o un proveedor de servicios designado.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pt-public-bodies-receive', 'de', 'Öffentliche Stellen müssen E-Rechnungen empfangen und verarbeiten', 'Einrichtungen der öffentlichen Verwaltung werden verpflichtet, strukturierte E-Rechnungen zu empfangen und zu verarbeiten, über die zentrale, von eSPap betriebene Plattform oder einen benannten Dienstleister.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pt-public-bodies-receive', 'fr', 'Les organismes publics doivent recevoir et traiter les factures électroniques', 'Les entités de l''administration publique deviennent tenues de recevoir et de traiter des factures électroniques structurées, via la plateforme centralisée exploitée par l''eSPap ou un prestataire de services désigné.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pt-b2g-large', 'es', 'Facturación electrónica B2G obligatoria para grandes empresas (en vigor desde enero de 2021)', 'Las grandes empresas que suministran a organismos de la administración pública deben emitir facturas electrónicas estructuradas en el formato nacional CIUS-PT (una implementación portuguesa de la norma EN 16931, mediante UBL 2.1 o CEFACT CII), transmitidas a través de la plataforma FE-AP gestionada por eSPap u otro canal aprobado. Portugal no tiene un mandato general de facturación electrónica B2B o B2C — este requisito se aplica específicamente al suministro al sector público.', '["Confirme que su sistema de facturación puede generar XML estructurado CIUS-PT válido, no solo una representación en PDF", "Conéctese a FE-AP o a un canal alternativo aprobado para transmitir facturas a organismos públicos"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pt-b2g-large', 'de', 'B2G-E-Rechnungsstellung für Großunternehmen verpflichtend (in Kraft seit Januar 2021)', 'Großunternehmen, die öffentliche Verwaltungsstellen beliefern, müssen strukturierte E-Rechnungen im nationalen Format CIUS-PT ausstellen (eine portugiesische Umsetzung von EN 16931, via UBL 2.1 oder CEFACT CII), übermittelt über die von eSPap betriebene FE-AP-Plattform oder einen anderen zugelassenen Kanal. Portugal hat keine allgemeine B2B- oder B2C-E-Invoicing-Vorgabe — diese Anforderung gilt speziell für die Belieferung des öffentlichen Sektors.', '["Bestätigen Sie, dass Ihr Rechnungssystem gültiges strukturiertes CIUS-PT-XML erzeugen kann, nicht nur eine PDF-Darstellung", "Verbinden Sie sich mit FE-AP oder einem zugelassenen alternativen Kanal zur Übermittlung von Rechnungen an öffentliche Stellen"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pt-b2g-large', 'fr', 'Facturation électronique B2G obligatoire pour les grandes entreprises (en vigueur depuis janvier 2021)', 'Les grandes entreprises fournissant des organismes de l''administration publique doivent émettre des factures électroniques structurées au format national CIUS-PT (une mise en œuvre portugaise de la norme EN 16931, via UBL 2.1 ou CEFACT CII), transmises via la plateforme FE-AP gérée par l''eSPap ou un autre canal approuvé. Le Portugal n''a pas d''obligation générale de facturation électronique B2B ou B2C — cette exigence s''applique spécifiquement à l''approvisionnement du secteur public.', '["Confirmez que votre système de facturation peut générer un XML structuré CIUS-PT valide, pas seulement une représentation PDF", "Connectez-vous à FE-AP ou à un canal alternatif approuvé pour transmettre les factures aux organismes publics"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pt-qr-code', 'es', 'El código QR se vuelve obligatorio en todas las facturas', 'Toda factura — en papel o electrónica, B2G o de otro tipo — debe llevar un código QR que permita su validación, junto con el requisito ya existente del código único de documento ATCUD.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pt-qr-code', 'de', 'QR-Code wird auf allen Rechnungen verpflichtend', 'Jede Rechnung — Papier oder elektronisch, B2G oder anderweitig — muss einen QR-Code zur Validierung tragen, zusätzlich zur bereits bestehenden Pflicht des eindeutigen ATCUD-Dokumentencodes.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pt-qr-code', 'fr', 'Le code QR devient obligatoire sur toutes les factures', 'Chaque facture — papier ou électronique, B2G ou autre — doit porter un code QR permettant sa validation, en plus de l''exigence déjà existante du code de document unique ATCUD.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pt-lei-82-2023', 'es', 'La Ley n.º 82/2023 modifica el marco B2G', 'Perfecciona y amplía la base legal establecida por la Ley n.º 111-B/2017.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pt-lei-82-2023', 'de', 'Gesetz Nr. 82/2023 ändert den B2G-Rahmen', 'Verfeinert und erweitert die durch Gesetz Nr. 111-B/2017 geschaffene Rechtsgrundlage.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pt-lei-82-2023', 'fr', 'La loi n° 82/2023 modifie le cadre B2G', 'Affine et élargit la base légale établie par la loi n° 111-B/2017.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pt-b2g-sme', 'es', 'El mandato B2G se extiende a pequeñas, medianas y microempresas', 'El requisito de facturación electrónica estructurada CIUS-PT para proveedores del sector público, que antes solo se aplicaba a las grandes empresas, se extiende ahora a pequeñas, medianas y microempresas. Por separado, independientemente del tamaño de la empresa o de si se aplica B2G, todas las facturas — en papel o electrónicas — deben emitirse ya con software certificado por la AT y llevar un código ATCUD, un código QR y una cadena de hash para garantizar la autenticidad.', '["Si suministra a algún organismo público portugués y aún no emite facturas estructuradas CIUS-PT, esto ya es una brecha de cumplimiento activa, no futura", "Independientemente de su situación B2G, confirme que su software de facturación está en la lista certificada por la AT — usar software no certificado invalida una factura independientemente de su contenido"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pt-b2g-sme', 'de', 'B2G-Vorgabe erstreckt sich auf kleine, mittlere und Kleinstunternehmen', 'Die Anforderung strukturierter CIUS-PT-E-Rechnungen für Lieferanten des öffentlichen Sektors, die zuvor nur für Großunternehmen galt, erstreckt sich nun auf kleine, mittlere und Kleinstunternehmen. Unabhängig von Unternehmensgröße oder B2G-Status müssen zudem alle Rechnungen — Papier oder elektronisch — bereits mit AT-zertifizierter Software ausgestellt werden und einen ATCUD-Code, einen QR-Code sowie eine Hash-Kette zur Echtheitsprüfung tragen.', '["Wenn Sie eine portugiesische öffentliche Stelle beliefern und noch keine strukturierten CIUS-PT-Rechnungen ausstellen, ist dies bereits eine aktive Compliance-Lücke, keine zukünftige", "Bestätigen Sie unabhängig von Ihrem B2G-Status, dass Ihre Rechnungssoftware auf der AT-zertifizierten Liste steht — die Nutzung nicht zertifizierter Software macht eine Rechnung unabhängig von ihrem Inhalt ungültig"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pt-b2g-sme', 'fr', 'L''obligation B2G s''étend aux petites, moyennes et micro-entreprises', 'L''exigence de facturation électronique structurée CIUS-PT pour les fournisseurs du secteur public, auparavant limitée aux grandes entreprises, s''étend désormais aux petites, moyennes et micro-entreprises. Par ailleurs, indépendamment de la taille de l''entreprise ou de l''applicabilité du B2G, toutes les factures — papier ou électroniques — doivent déjà être émises à l''aide d''un logiciel certifié par l''AT et porter un code ATCUD, un code QR et une chaîne de hachage garantissant l''authenticité.', '["Si vous fournissez un organisme public portugais et n''émettez pas encore de factures structurées CIUS-PT, il s''agit désormais d''un écart de conformité actif, non futur", "Indépendamment de votre statut B2G, confirmez que votre logiciel de facturation figure sur la liste certifiée par l''AT — l''utilisation d''un logiciel non certifié invalide une facture quel que soit son contenu"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pt-pdf-valid-through-2026', 'es', 'Las facturas en PDF siguen siendo válidas sin QES, hasta el 31 de diciembre de 2026', 'Confirmado mediante el Presupuesto del Estado 2026 (aprobado el 27 de noviembre de 2025): las facturas en PDF emitidas por software certificado, con ATCUD y código QR, siguen siendo legalmente válidas sin una Firma Electrónica Cualificada hasta esta fecha.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pt-pdf-valid-through-2026', 'de', 'PDF-Rechnungen bleiben ohne QES gültig, bis zum 31. Dezember 2026', 'Bestätigt durch den Staatshaushalt 2026 (genehmigt am 27. November 2025): Von zertifizierter Software ausgestellte PDF-Rechnungen mit ATCUD und QR-Code bleiben bis zu diesem Datum ohne Qualifizierte Elektronische Signatur rechtsgültig.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pt-pdf-valid-through-2026', 'fr', 'Les factures PDF restent valables sans QES, jusqu''au 31 décembre 2026', 'Confirmé par le Budget de l''État 2026 (approuvé le 27 novembre 2025) : les factures PDF émises par un logiciel certifié, avec ATCUD et code QR, restent légalement valables sans Signature Électronique Qualifiée jusqu''à cette date.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pt-qes', 'es', 'Se exige la Firma Electrónica Cualificada (QES) para las facturas en PDF', 'Las facturas en PDF en transacciones B2B y B2C requerirán una Firma Electrónica Cualificada de un prestador de servicios de confianza cualificado registrado en la UE para seguir siendo legalmente válidas — aplazado desde una fecha original de 2026 mediante el Presupuesto del Estado 2026. Hasta el 31 de diciembre de 2026, las facturas en PDF emitidas por software certificado con ATCUD y código QR siguen siendo válidas sin QES.', '["Identifique un prestador de servicios de confianza cualificado registrado en la UE para la QES bien antes del plazo de 2027 — es un paso de contratación diferenciado, no una opción de software", "No asuma que el cumplimiento de los requisitos existentes de ATCUD/QR/software certificado cubre esto — la QES es una capa nueva y adicional específicamente para las facturas en PDF"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pt-qes', 'de', 'Qualifizierte Elektronische Signatur (QES) für PDF-Rechnungen erforderlich', 'PDF-Rechnungen in B2B- und B2C-Transaktionen benötigen eine Qualifizierte Elektronische Signatur eines EU-gelisteten qualifizierten Vertrauensdiensteanbieters, um weiterhin rechtsgültig zu sein — verschoben von einem ursprünglichen Datum 2026 über den Staatshaushalt 2026. Bis zum 31. Dezember 2026 bleiben von zertifizierter Software ausgestellte PDF-Rechnungen mit ATCUD und QR-Code auch ohne QES gültig.', '["Identifizieren Sie einen EU-gelisteten qualifizierten Vertrauensdiensteanbieter für QES rechtzeitig vor der Frist 2027 — dies ist ein eigener Beschaffungsschritt, keine Softwareeinstellung", "Gehen Sie nicht davon aus, dass die Einhaltung der bestehenden ATCUD-/QR-/Zertifizierungssoftware-Anforderungen dies bereits abdeckt — QES ist eine echte, zusätzliche Ebene speziell für PDF-Rechnungen"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pt-qes', 'fr', 'La Signature Électronique Qualifiée (QES) requise pour les factures PDF', 'Les factures PDF dans les transactions B2B et B2C nécessiteront une Signature Électronique Qualifiée d''un prestataire de services de confiance qualifié inscrit sur liste européenne pour rester légalement valables — reportée d''une date initiale de 2026 via le Budget de l''État 2026. Jusqu''au 31 décembre 2026, les factures PDF émises par un logiciel certifié avec ATCUD et code QR restent valables sans QES.', '["Identifiez un prestataire de services de confiance qualifié inscrit sur liste européenne pour la QES bien avant l''échéance de 2027 — il s''agit d''une étape d''approvisionnement distincte, pas d''un simple paramètre logiciel", "Ne supposez pas que la conformité aux exigences existantes ATCUD/QR/logiciel certifié couvre déjà cela — la QES est une couche véritablement nouvelle et supplémentaire spécifique aux factures PDF"]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pt-saft-full', 'es', 'El archivo SAF-T de contabilidad completa se vuelve obligatorio', 'Vence la primera presentación anual obligatoria del archivo SAF-T de contabilidad completa, cubriendo las transacciones del ejercicio 2027 — a su vez aplazada desde un calendario anterior de 2026 mediante el mismo proceso del Presupuesto del Estado.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pt-saft-full', 'de', 'Vollständige Buchführungs-SAF-T-Datei wird verpflichtend', 'Die erste verpflichtende jährliche Einreichung der vollständigen Buchführungs-SAF-T-Datei, die Transaktionen des Geschäftsjahres 2027 abdeckt, wird fällig — selbst verschoben von einem früheren 2026er-Zeitplan über denselben Staatshaushaltsprozess.', '[]');
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('pt-saft-full', 'fr', 'Le fichier SAF-T comptable complet devient obligatoire', 'La première soumission annuelle obligatoire du fichier SAF-T comptable complet, couvrant les transactions de l''exercice 2027, devient exigible — elle-même reportée d''un calendrier 2026 antérieur via le même processus de Budget de l''État.', '[]');
